 8: export type PersianBrailleTranslationFailureCode =
 9:   | "PREPROCESSING_FAILED"
10:   | "UNKNOWN_CHARACTER"
11:   | "UNKNOWN_SEQUENCE"
12:   | "AMBIGUOUS_MATCH"
13:   | "UNSUPPORTED_ENGINE_STATE";
14: 
15: export interface PersianBrailleUnicodeLocation {
16:   readonly codePointIndex: number;
17:   readonly utf16Index: number;
18: }
19: 
20: export interface PersianBrailleProfileInfo {
21:   readonly id: string;
22:   readonly version: string;
23:   readonly status: string;
24:   readonly direction: "print-to-braille";
25: }
26: 
27: export interface PersianBrailleTranslationSuccess {
28:   readonly ok: true;
29:   readonly input: string;
30:   readonly profile: PersianBrailleProfileInfo;
31:   readonly normalizedText: string;
32:   readonly cells: readonly string[];
33:   readonly unicodeBraille: string;
34:   readonly structuralTokens: readonly string[];
35: }
