37: export interface PersianBrailleTranslationFailure {
38:   readonly ok: false;
39:   readonly input: string;
40:   readonly profile: PersianBrailleProfileInfo;
41:   readonly code: PersianBrailleTranslationFailureCode;
42:   readonly message: string;
43:   readonly location?: PersianBrailleUnicodeLocation;
44:   readonly character?: string;
45:   readonly codePoint?: string;
46:   readonly candidateRuleIds?: readonly string[];
47:   readonly causeCode?: string;
48: }
