50: export type PersianBrailleTranslationResult =
51:   | PersianBrailleTranslationSuccess
52:   | PersianBrailleTranslationFailure;
53: 
54: export interface PersianBrailleTranslationErrorData {
55:   readonly code: PersianBrailleTranslationFailureCode;
56:   readonly result: PersianBrailleTranslationFailure;
57: }
