59: export interface PersianBrailleTranslator {
60:   /**
61:    * Immutable metadata for the bundled profile used by this translator.
62:    */
63:   readonly profile: PersianBrailleProfileInfo;
64: 
65:   /**
66:    * Translate print text to Persian Braille without throwing for expected
67:    * translation failures.
68:    */
69:   translate(
70:     input: string,
71:   ): PersianBrailleTranslationResult;
72: 
73:   /**
74:    * Translate print text to Persian Braille and throw the SDK translation
75:    * error for an expected translation failure.
76:    */
77:   translateOrThrow(
78:     input: string,
79:   ): PersianBrailleTranslationSuccess;
80: }
