201:     readonly structuralTokens:
202:       readonly string[];
203:   },
204: ): PersianBrailleTranslationSuccess {
205:   return Object.freeze({
206:     ok: true,
207:     input,
208:     profile,
209:     normalizedText:
210:       outcome.normalizedText,
211:     cells:
212:       freezeStrings(outcome.cells),
213:     unicodeBraille:
214:       outcome.unicodeBraille,
215:     structuralTokens:
