222: function projectFailure(
223:   input: string,
224:   profile: PersianBrailleProfileInfo,
225:   outcome: unknown,
226: ): PersianBrailleTranslationFailure {
227:   const message =
228:     readString(outcome, "message");
229: 
230:   if (message === undefined) {
231:     throw new Error(
232:       "Core translation failure did not expose a message.",
233:     );
234:   }
235: 
236:   const failure: {
237:     ok: false;
238:     input: string;
239:     profile: PersianBrailleProfileInfo;
240:     code: PersianBrailleTranslationFailureCode;
241:     message: string;
242:     location?: PersianBrailleUnicodeLocation;
243:     character?: string;
244:     codePoint?: string;
245:     candidateRuleIds?: readonly string[];
246:     causeCode?: string;
247:   } = {
248:     ok: false,
249:     input,
250:     profile,
251:     code:
252:       readFailureCode(outcome),
253:     message,
254:   };
255: 
256:   const location =
257:     readLocation(outcome);
258:   const character =
259:     readString(
260:       outcome,
261:       "character",
262:     );
263:   const codePoint =
264:     readString(

268:   const candidateRuleIds =
269:     readStringArray(
270:       outcome,
271:       "candidateRuleIds",
272:     );
273:   const causeCode =
274:     readCauseCode(outcome);
275: 
276:   if (location !== undefined) {
277:     failure.location = location;
278:   }
279: 
280:   if (character !== undefined) {
281:     failure.character = character;
282:   }
283: 
284:   if (codePoint !== undefined) {
285:     failure.codePoint = codePoint;
286:   }
287: 
288:   if (
289:     candidateRuleIds !== undefined
290:   ) {
291:     failure.candidateRuleIds =
292:       candidateRuleIds;
293:   }
294: 
295:   if (causeCode !== undefined) {
296:     failure.causeCode = causeCode;
297:   }
298: 
299:   return Object.freeze(failure);
300: }
