302: export class PersianBrailleTranslationError
303:   extends Error
304:   implements PersianBrailleTranslationErrorData {
305:   readonly code:
306:     PersianBrailleTranslationFailureCode;
307: 
308:   readonly result:
309:     PersianBrailleTranslationFailure;
310: 
311:   constructor(
312:     result:
313:       PersianBrailleTranslationFailure,
314:   ) {
315:     super(result.message);
316: 
317:     this.name =
318:       "PersianBrailleTranslationError";
319:     this.code = result.code;
320:     this.result = result;
321: 
322:     Object.freeze(this);
323:   }
324: }
