326: class CoreBackedPersianBrailleTranslator
327:   implements PersianBrailleTranslator {
328:   readonly profile:
329:     PersianBrailleProfileInfo;
330: 
331:   readonly #coreTranslator =
332:     createForwardTranslator();
333: 
334:   constructor() {
335:     this.profile =
336:       createProfileInfo();
337:   }
338: 
339:   translate(
340:     input: string,
341:   ): PersianBrailleTranslationResult {
342:     const outcome =
343:       this.#coreTranslator.translate(
344:         input,
345:       );
346: 
347:     if (outcome.ok) {
348:       return projectSuccess(
349:         input,
350:         this.profile,
351:         outcome,
352:       );
353:     }
354: 
355:     return projectFailure(
356:       input,
357:       this.profile,
358:       outcome,
359:     );
360:   }
361: 
362:   translateOrThrow(
363:     input: string,
364:   ): PersianBrailleTranslationSuccess {
365:     const result =
366:       this.translate(input);
367: 
368:     if (!result.ok) {
369:       throw new PersianBrailleTranslationError(
370:         result,
371:       );
372:     }
373: 
374:     return result;
375:   }
376: }
377: 
378: export function createPersianBrailleTranslator(
379: ): PersianBrailleTranslator {
380:   return new CoreBackedPersianBrailleTranslator();
381: }

